  const openReportSetup = (template: "standard" | "blank") => { const period = completedPeriod("monthly"); const client = workspaceClients.find((item) => item.id === selectedClientId); setReportMetadata({ title: client ? `تقرير ${period.label} — ${client.name}` : `تقرير ${period.label}`, clientId: selectedClientId, periodStart: period.periodStart, periodEnd: period.periodEnd, periodType: "monthly" }); setSetupTemplate(template); setReportSetupOpen(true); };
